	@Test
	void repeatedBulkTupleOrdersDoNotInventNativeCommitsOrDoubleContextCounts() throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(), config(), null)) {
			store.beginBulkOwnership();
			var outgoing = List.of(new long[] { 10, 20, 30, 0 }, new long[] { 11, 20, 31, 7 }).iterator();
			assertThat(store.appendBulkIndex("spoc", tuple -> {
				if (!outgoing.hasNext()) {
					return false;
				}
				System.arraycopy(outgoing.next(), 0, tuple, 0, 4);
				return true;
			}, 10, 4096)).isEqualTo(2);
			long afterFirstOrder = store.trustedTransactionId();
			var incoming = List.of(new long[] { 20, 30, 10, 0 }, new long[] { 20, 31, 11, 7 }).iterator();
			assertThat(store.appendBulkIndex("posc", tuple -> {
				if (!incoming.hasNext()) {
					return false;
				}
				System.arraycopy(incoming.next(), 0, tuple, 0, 4);
				return true;
			}, 10, 4096)).isEqualTo(2);
			assertThat(store.trustedTransactionId()).isEqualTo(afterFirstOrder);
			var contexts = List.of(new long[] { 0, 1 }, new long[] { 7, 1 }).iterator();
			store.appendBulkContexts(tuple -> {
				if (!contexts.hasNext()) {
					return false;
				}
				System.arraycopy(contexts.next(), 0, tuple, 0, 2);
				return true;
			}, 10, 4096);
			assertThat(store.trustedTransactionId()).isEqualTo(afterFirstOrder);
			assertThat(store.explicitIndexEntryCounts()).containsEntry("psoc", 2L).containsEntry("posc", 2L);
		}
	}

