	private void createRepository() {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		store.init();
		try (SailConnection connection = store.getConnection()) {
			var values = store.getValueFactory();
			var predicate = values.createIRI("urn:integrity:predicate");
			connection.begin();
			connection.addStatement(values.createIRI("urn:integrity:subject"), predicate,
					values.createLiteral("explicit"));
			((InferencerConnection) connection).addInferredStatement(values.createIRI("urn:integrity:inferred"),
					predicate, values.createLiteral("inferred"), values.createIRI("urn:integrity:graph"));
			connection.commit();
		} finally {
			store.shutDown();
		}
	}

	private static void createNativeLegacyFixture(Path environment) throws IOException {
		nativeTransaction(environment, true, (stack, txn) -> {
			for (String order : List.of("spoc", "posc")) {
				for (boolean explicit : new boolean[] { true, false }) {
					int dbi = LmdbUtil.openDatabaseWithTxn(txn, TripleIndex.nativeDatabaseName(order, explicit),
							MDB_CREATE);
					for (List<Long> quad : explicit ? EXPLICIT : INFERRED) {
						put(stack, txn, dbi,
								TripleIndex.encodeKey(order, quad.get(0), quad.get(1), quad.get(2), quad.get(3)),
								new byte[0]);
					}
				}
			}
			int contexts = LmdbUtil.openDatabaseWithTxn(txn, "contexts", MDB_CREATE);
			for (long context : new long[] { 0, 7, 8 }) {
				put(stack, txn, contexts, LmdbCompatibilityFixtures.unsigned(context),
						LmdbCompatibilityFixtures.unsigned(context == 7 ? 2 : 1));
			}
			LmdbUtil.openDatabaseWithTxn(txn, "namespaces", MDB_CREATE);
			return null;
		});
	}

	private static void assertMigratedNativeFixture(Path environment) throws Exception {
		try (TripleStore store = new TripleStore(environment.toFile(), config(), null);
				Txn txn = store.getTxnManager().createReadTxn()) {
			for (boolean explicit : new boolean[] { true, false }) {
				Set<List<Long>> records = new HashSet<>();
				try (RecordIterator iterator = store.getTriples(txn, -1, -1, -1, -1, explicit)) {
					for (long[] quad = iterator.next(); quad != null; quad = iterator.next()) {
						assertThat(records.add(List.of(quad[0], quad[1], quad[2], quad[3]))).isTrue();
					}
				}
				assertThat(records).containsExactlyInAnyOrderElementsOf(explicit ? EXPLICIT : INFERRED);
			}
		}
		assertThat(nativeRecords(environment).keySet()).containsExactlyInAnyOrderElementsOf(ADJACENCY_DATABASES);
		nativeTransaction(environment, false, (stack, txn) -> {
			LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn);
			assertThat(adjacency.count(txn, true)).isEqualTo(2);
			assertThat(adjacency.count(txn, false)).isEqualTo(2);
			assertThat(adjacency.contextTotal(txn, 0)).isEqualTo(1);
			assertThat(adjacency.contextTotal(txn, 7)).isEqualTo(2);
			assertThat(adjacency.contextTotal(txn, 8)).isEqualTo(1);
			return null;
		});
	}

	private static void deleteFirstIncomingPage(MemoryStack stack, long txn, int pages) throws IOException {
		PointerBuffer handle = stack.mallocPointer(1);
		E(mdb_cursor_open(txn, pages, handle));
		long cursor = handle.get(0);
		try {
			MDBVal key = MDBVal.calloc(stack);
			MDBVal value = MDBVal.calloc(stack);
			int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
			while (result == MDB_SUCCESS) {
				if (key.mv_data().get(0) == 1) {
					E(mdb_cursor_del(cursor, 0));
					return;
				}
				result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
			}
			if (result != MDB_NOTFOUND) {
				E(result);
			}
			throw new AssertionError("Fixture must contain an explicit incoming adjacency page");
		} finally {
			mdb_cursor_close(cursor);
		}
	}

	private static Map<String, Map<String, String>> nativeRecords(Path environment) throws IOException {
		return nativeTransaction(environment, false, (stack, txn) -> {
			int catalog = LmdbUtil.openDatabaseWithTxn(txn, null, 0);
			Map<String, Map<String, String>> result = new HashMap<>();
			for (String encoded : databaseRecords(stack, txn, catalog).keySet()) {
				String name = new String(HexFormat.of().parseHex(encoded), StandardCharsets.UTF_8);
				int dbi = LmdbUtil.openDatabaseWithTxn(txn, name, 0);
				result.put(name, databaseRecords(stack, txn, dbi));
			}
			return result;
		});
	}

	private static Map<String, String> databaseRecords(MemoryStack stack, long txn, int dbi) throws IOException {
		PointerBuffer handle = stack.mallocPointer(1);
		E(mdb_cursor_open(txn, dbi, handle));
		long cursor = handle.get(0);
		try {
			Map<String, String> result = new HashMap<>();
			MDBVal key = MDBVal.calloc(stack);
			MDBVal value = MDBVal.calloc(stack);
			int rc = mdb_cursor_get(cursor, key, value, MDB_FIRST);
			while (rc == MDB_SUCCESS) {
				byte[] keyBytes = new byte[(int) key.mv_size()];
				byte[] valueBytes = new byte[(int) value.mv_size()];
				key.mv_data().duplicate().get(keyBytes);
				if (valueBytes.length != 0) {
					value.mv_data().duplicate().get(valueBytes);
				}
				result.put(HexFormat.of().formatHex(keyBytes), HexFormat.of().formatHex(valueBytes));
				rc = mdb_cursor_get(cursor, key, value, MDB_NEXT);
			}
			if (rc != MDB_NOTFOUND) {
				E(rc);
			}
			return result;
		} finally {
			mdb_cursor_close(cursor);
		}
	}

	private static void put(MemoryStack stack, long txn, int dbi, byte[] key, byte[] value) throws IOException {
		MDBVal nativeValue = MDBVal.calloc(stack);
		if (value.length != 0) {
			nativeValue.mv_data(stack.bytes(value));
		}
		E(mdb_put(txn, dbi, MDBVal.calloc(stack).mv_data(stack.bytes(key)), nativeValue, 0));
	}

	private static <T> T nativeTransaction(Path directory, boolean write, LmdbUtil.Transaction<T> action)
			throws IOException {
		if (write) {
			Files.createDirectories(directory);
		}
		long environment = NULL;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
			E(mdb_env_set_maxdbs(environment, 128));
			if (write) {
				E(mdb_env_set_mapsize(environment, 64L * 1024 * 1024));
			}
			E(mdb_env_open(environment, directory.toString(), MDB_NOTLS | (write ? 0 : MDB_RDONLY), 0664));
			return write ? LmdbUtil.writeTransaction(environment, action)
					: LmdbUtil.readTransaction(environment, action);
		} finally {
			if (environment != NULL) {
				mdb_env_close(environment);
			}
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false).setForceSync(true);
	}
